package dev.homecontrol.app;
import android.app.*;
import android.widget.*;
import android.view.*;
import android.text.InputType;
import org.json.*;
import java.util.*;

/** Camera-side SMB discovery and access configuration, independent of the official app. */
final class CameraNasDialog {
 private final Activity owner;private final AppUi ui;private final String id;private Dialog dialog;private LinearLayout rows;private TextView feedback;private JSONObject config;private boolean busy;
 CameraNasDialog(Activity a,AppUi u,String id){owner=a;ui=u;this.id=id;}
 void show(){LinearLayout body=ui.column();rows=ui.column();body.addView(rows);feedback=ui.text("正在读取 NAS 配置…",13,ui.muted,false);body.addView(feedback);ui.space(body,10);TextView search=button("搜索摄像机所在网络的 NAS",()->request("camera.nas.scan",new JSONObject(),answer->discovered(CameraNas.servers(answer))));body.addView(search,new LinearLayout.LayoutParams(-1,ui.dp(52)));dialog=AppSheet.show(owner,"NAS 存储访问设置",body,null,null);dialog.setOnDismissListener(v->{config=null;rows.removeAllViews();});request("camera.nas.get",new JSONObject(),answer->{config=CameraNas.config(answer);patch();});}
 private TextView button(String label,Runnable action){TextView v=AppSheet.button(owner,ui,label,false);v.setOnClickListener(w->action.run());return v;}
 interface Result{void accept(Object result)throws Exception;}
 private void request(String op,JSONObject args,Result next){if(busy)return;busy=true;new Thread(()->{Object value=null;String error=null;try{value=MijiaCloud.feature(owner,id,op,args);}catch(Exception e){error=op.endsWith("set")?"设置结果未确认，请核对设备状态；不会自动重发":"摄像机未返回 NAS 信息，请确认摄像机与 NAS 在线且在同一网络";}Object answer=value;String problem=error;owner.runOnUiThread(()->{busy=false;if(!dialog.isShowing())return;if(problem!=null){feedback.setText(problem);return;}try{next.accept(answer);feedback.setText(op.endsWith("set")?"设置已受理，请稍后核对实际存储状态":"");}catch(Exception e){feedback.setText("此型号返回的 NAS 信息暂不能解析，未修改设置");}});},"JiaJuNas").start();}
 private void patch(){rows.removeAllViews();if(config==null)return;int state=config.optInt("state");String label=state==1?"等待传输":state==2?"已暂停":state==3?"正在传输":"状态待确认";rows.addView(ui.text("NAS 存储 · "+label+(config.optInt("error_code")!=0?" · 设备报告异常":""),14,ui.text,true));JSONObject share=config.optJSONObject("share");if(share!=null&&!share.optString("name").isEmpty()){ui.space(rows,8);rows.addView(ui.text(share.optString("name")+" / "+share.optString("dir"),13,ui.muted,false));ui.space(rows,10);rows.addView(button("修改 NAS 访问设置",()->edit(share)),new LinearLayout.LayoutParams(-1,ui.dp(50)));}}
 private void discovered(JSONArray servers){LinearLayout body=ui.column();int count=0;for(int i=0;i<Math.min(100,servers.length());i++){JSONObject server=servers.optJSONObject(i);if(server==null||!server.has("addr")||!server.has("type"))continue;JSONObject share=new JSONObject();try{share.put("addr",server.get("addr")).put("type",server.get("type"));for(String k:new String[]{"name","group","dir","user","pass"})share.put(k,server.optString(k));}catch(Exception ignored){continue;}body.addView(button(server.optString("name","NAS"),()->edit(share)),new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(body,6);count++;}if(count==0)body.addView(ui.text("摄像机未发现 NAS。请确认 NAS 已开启 SMB 共享，且与摄像机处于同一网络。",14,ui.muted,false));AppSheet.show(owner,"选择 NAS",body,null,null);}
 private EditText field(LinearLayout body,String title,String value,boolean password){body.addView(ui.text(title,13,ui.muted,false));EditText input=new EditText(owner);AppSheet.input(input,ui);input.setSingleLine(true);input.setInputType(InputType.TYPE_CLASS_TEXT|(password?InputType.TYPE_TEXT_VARIATION_PASSWORD:0));input.setContentDescription(title);input.setText(value);body.addView(input,new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(body,10);return input;}
 private void edit(JSONObject original){LinearLayout body=ui.column();EditText name=field(body,"NAS 名称",original.optString("name"),false),group=field(body,"工作组",original.optString("group"),false),directory=field(body,"共享目录",original.optString("dir"),false),user=field(body,"用户名",original.optString("user"),false),pass=field(body,"密码", "",true);pass.setHint(original.optString("pass").isEmpty()?"匿名访问可留空":"留空保留原密码");LinkedHashMap<String,String> states=new LinkedHashMap<>();states.put("3","开启存储");states.put("2","暂停存储");final int[] selected={config!=null&&config.optInt("state")==2?2:3};ChoiceView state=new ChoiceView(owner,ui,"NAS 存储",states,Integer.toString(selected[0]),220,key->selected[0]=Integer.parseInt(key));body.addView(state);final Dialog[] editor=new Dialog[1];editor[0]=AppSheet.show(owner,"NAS 访问设置",body,"保存",()->{if(busy){Toast.makeText(owner,"正在读取，请稍候",Toast.LENGTH_SHORT).show();return;}try{JSONObject share=new JSONObject(original.toString()).put("name",name.getText().toString().trim()).put("group",group.getText().toString().trim()).put("dir",directory.getText().toString().trim()).put("user",user.getText().toString());String password=pass.getText().toString();share.put("pass",password.isEmpty()?original.optString("pass"):password);JSONObject settings=new JSONObject().put("state",selected[0]).put("sync_interval",config!=null&&config.optInt("sync_interval")>0?config.optInt("sync_interval"):300).put("video_retention_time",config!=null&&config.optInt("video_retention_time")>0?config.optInt("video_retention_time"):7776000).put("share",share);CameraNas.params("camera.nas.set",settings);request("camera.nas.set",settings,answer->{request("camera.nas.get",new JSONObject(),fresh->{config=CameraNas.config(fresh);patch();});});pass.setText("");editor[0].dismiss();}catch(Exception e){Toast.makeText(owner,e.getMessage(),Toast.LENGTH_LONG).show();}});editor[0].setOnDismissListener(v->pass.setText(""));}
}
